script:
country_event = {
	id = shroud.6000
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		# Setup timed events
		country_event = { id = shroud.6050 months = 3 }
		country_event = { id = shroud.6125 years = 12 }
		save_event_target_as = current_mindwarden_country

		# Spawn Exiled
		create_exiled_country = yes

		# Handle starting systems
		solar_system = {
			save_event_target_as = mindwarden_system

			# flag cleanup
			every_neighbor_system = {
				remove_star_flag = empire_cluster
				every_neighbor_system = {
					remove_star_flag = empire_cluster
				}
			}

			if = {
				limit = {
					OR = {
						is_rim_system = no
						any_neighbor_system = {
							OR = {
								has_special_star_flag_trigger = yes
								has_natural_wormhole = yes
								any_system_planet = {
									is_colonizable = yes
								}
							}
						}
					}
				}
				closest_system = {
					limit = {
						is_rim_system = yes
						has_special_star_flag_trigger = no
						has_natural_wormhole = no
						NOT = { has_star_flag = mindwarden_target_system }
						NOT = {
							any_system_planet = {
								is_colonizable = yes
							}
						}
						count_neighbor_system = {
							count > 0
						}
						any_neighbor_system = {
							distance = {
								source = prev
								max_distance < 60
								type = euclidean
							}
						}
					}
					set_star_flag = mindwarden_target_system
					save_event_target_as = target_system
				}
			}
			else = {
				save_event_target_as = target_system
			}

			set_spawn_system_batch = begin
			if = {
				limit = {
					has_star_flag = sol
				}
				event_target:target_system = {
					spawn_system = {
						min_distance >= 20
						max_distance <= 25
						direction = rimwards
						initializer = "mindwarden_sol_buffer_system"
						hyperlane = no
						is_discovered = no
						effect = {
							save_event_target_as = mindwarden_buffer_system@root
						}
					}
				}
				else = {
					event_target:target_system = {
						spawn_system = {
							min_distance >= 20
							max_distance <= 25
							direction = rimwards
							initializer = "mindwarden_buffer_system"
							hyperlane = no
							is_discovered = no
							effect = {
								save_event_target_as = mindwarden_buffer_system@root
							}
						}
					}
				}
			}
			set_spawn_system_batch = end

			# System must be moved AFTER spawning Exiled systems, so resetting TI works correctly
			if = {
				limit = {
					event_target:target_system = {
						NOT = { is_same_value = event_target:mindwarden_system }
					}
				}
				move_system = {
					target = event_target:target_system
					min_distance >= 10
					max_distance <= 15
					direction = rimwards
					max_jumps = 0
					hyperlane = yes
					reset_terra_incognita = yes
				}
				every_neighbor_system_euclidean = {
					limit = {
						NOR = {
							has_star_flag = surveillance_supercomputer_system
							has_special_star_flag_trigger = yes
							has_natural_wormhole = yes
							any_system_planet = {
								is_colonizable = yes
							}
						}
						NOT = { has_hyperlane_to = prev }
						distance = {
							source = prev
							max_distance < 60
							type = euclidean
						}
					}
					add_hyperlane = {
						from = prev
						to = this
					}
				}
			}
			if = {
				limit = {
					count_neighbor_system = {
						count = 0
					}
				}
				# Safekeep
				random_neighbor_system_euclidean = {
					limit = {
						NOR = {
							has_star_flag = surveillance_supercomputer_system
							has_star_flag = exiled_system
						}
						distance = {
							source = prev
							max_distance < 80
							type = euclidean
						}
					}
					add_hyperlane = {
						from = prev
						to = this
					}
				}
			}
			if = {
				limit = {
					NOT = { has_hyperlane_to = event_target:mindwarden_buffer_system@root }
				}
				add_hyperlane = {
					from = event_target:mindwarden_buffer_system@root
					to = this
				}
			}

			every_neighbor_system = {
				set_star_flag = empire_cluster
				every_neighbor_system = {
					set_star_flag = empire_cluster
				}
			}

			event_target:current_exiled_country = {
				every_system_within_border = {
					spawn_psionic_aura = {
						owner = prev
						type = exiled_aura
						update_type = no
					}
					set_aura_intensity = 999 # So it can trigger on_progress_complete only when it can increase
				}
			}

			random_system_planet = {
				limit = {
					NOT = { has_carrier_flag = starting_deposit }
					NOT = { has_carrier_flag = ignore_startup_effect }
					OR = {
						is_planet_class = pc_gas_giant
						is_planet_class = pc_toxic
						is_planet_class = pc_frozen
						is_planet_class = pc_barren_cold
						is_planet_class = pc_barren
						is_planet_class = pc_asteroid
					}
				}
				set_carrier_flag = starting_deposit
				add_deposit = d_zro_deposit_1
				save_event_target_as = zro_deposit_planet
			}
		}

		if = {
			limit = { exists = event_target:zro_deposit_planet }
			# To set zro as discovered
			random_owned_ship = {
				ship_event = {
					id = action.941
					days = 1
					scopes = {
						from = event_target:zro_deposit_planet
					}
				}
			}
		}
	}
}

