country_event = {
	id = shroud.6230
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		has_origin = origin_mindwardens
		fromfrom = {
			planet = {
				is_same_value = root.home_planet
			}
		}
	}

	immediate = {
		if = {
			limit = {
				fromfrom = { has_building = building_ancient_ward_1 }
			}
			set_country_flag = had_ancient_ward
		}
		else_if = {
			limit = {
				fromfrom = { has_building = building_ancient_ward_2 }
			}
			set_country_flag = had_grand_ward
		}
		if = {
			limit = {
				has_country_flag = shroud_seal_dismantled
			}
			export_trigger_value_to_variable = {
				trigger = timed_flag_days_left
				parameters = {
					flag = psionic_war_no_shroud_seal
				}
				variable = time_left_before_psionic_war
			}
		}
		else = {
			export_trigger_value_to_variable = {
				trigger = timed_flag_days_left
				parameters = {
					flag = psionic_war_with_shroud_seal
				}
				variable = time_left_before_psionic_war
			}
		}
		if = {
			limit = {
				check_variable = {
					which = time_left_before_psionic_war
					value > 0
				}
			}
			set_country_flag = block_psionic_war
		}
		if = {
			limit = {
				NOT = { has_country_flag = mindwarden_ward_upgraded }
			}
			country_event = { id = shroud.6231 }
		}
	}
}

