	id = shroud.8000
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		random_planet_within_border = {
			limit = {
				carrier_is_type = planet
				is_capital = no
				is_moon = no
				is_star = no
				is_asteroid = no
				is_artificial = no
				solar_system = {
					count_system_planet = {
						limit = {
							carrier_is_type = planet
							NOT = { is_same_value = prev }
							is_capital = no
							is_moon = no
							is_star = no
							is_asteroid = no
							is_artificial = no
							root.capital_scope = {
								compare_distance = {
									closer_object = prev
									further_object = prevprevprev
								}
							}
						}
						count = 0
					}
				}
			}
			save_event_target_as = closest_shrouded_planet
		}
		if = {
			limit = { exists = event_target:closest_shrouded_planet }
			event_target:closest_shrouded_planet = {
				save_global_event_target_as = shrouded_planet@root
				change_pc = pc_shrouded
				if = {
					limit = { has_deposit_for = shipclass_mining_station }
					clear_deposits = yes
				}
				add_deposit = d_zro_deposit_1
				# Shrouded Worlds can't be terraforming candidates.
				remove_modifier = terraforming_candidate
				remove_modifier = frozen_terraforming_candidate
				remove_modifier = toxic_terraforming_candidate
			}
		}

		refresh_endbringers_paranoia_modifier = yes

		country_event = {
			id = shroud.8010
			days = 30
		}
	}
}

