script:
situation_event = {
	id = shroud.8340
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		exists = owner
		owner = {
			has_origin = origin_endbringers
		}
		current_situation_approach = approach_situation_breach_shroud_endbringers_blind
	}

	immediate = {
		owner = {
			# Find a pop group without the blindness trait
			random_owned_pop_group = {
				limit = {
					NOT = { has_trait = trait_blindness }
				}
				# Save the pop group as an event target
				save_event_target_as = old_pop_group
				# Save their species as an event target
				species = {
					save_event_target_as = old_species
				}
				# If a modified species hasn't been created, create one
				# and save them as an event target
				if = {
					limit = {
						NOT = {
							any_galaxy_species = {
								has_species_flag = blinded_species_of_species@event_target:old_species
								has_species_flag = blinded_species_of_empire@root.owner
							}
						}
					}
					create_species = {
						is_mod = yes
						name = this
						plural = this
						class = this
						portrait = this
						traits = this
						can_be_modified = this
						homeworld = this
						namelist = this
						gender = this
						effect = {
							modify_species = {
								species = this
								add_trait = trait_blindness
								change_scoped_species = no

								effect = {
									set_species_flag = blinded_species_of_species@event_target:old_species
									set_species_flag = blinded_species_of_empire@root.owner
									save_event_target_as = target_species
								}
							}
						}
					}
				}
				# If a modified species does exist, save them as the event target
				else = {
					random_galaxy_species = {
						limit = {
							has_species_flag = blinded_species_of_species@event_target:old_species
							has_species_flag = blinded_species_of_empire@root.owner
						}
						save_event_target_as = target_species
					}
				}
				# Scope back to the planet
				# Create the empty pop group
				# and move pops into it
				planet = {
					create_pop_group = {
						pop_group = event_target:old_pop_group
						species = event_target:target_species
						size = 0
						effect = {
							transfer_pop_amount = {
								source = event_target:old_pop_group
								target = this
								amount = @nb_blinded_pop
							}
						}
					}
				}
			}
		}
	}
}

